public class ProfileTarget {

    static int countWords(String text) {
        return text.split(" +").length;
    }

    // Anti-patterns: (1) String += in loop creates O(n) objects
    //               (2) Pattern compiled on every countWords call via split()
    static String buildReport(int n) {
        String result = "";
        String sample = "hello world java";
        for (int i = 0; i < n; i++) {
            result += countWords(sample);
        }
        return result;
    }

    public static void main(String[] args) {
        buildReport(10_000);
        buildReport(10_000);
        buildReport(10_000);
        long start = System.nanoTime();
        buildReport(10_000);
        long ms = (System.nanoTime() - start) / 1_000_000;
        System.out.println("buildReport(10000) took " + ms + "ms");
    }
}

