import java.util.regex.Pattern;

public class ProfileTargetFixed {
    private static final Pattern SPACE = Pattern.compile(" +");

    static int countWords(String text) {
        return SPACE.split(text).length;
    }

    static String buildReport(int n) {
        StringBuilder sb = new StringBuilder();
        String sample = "hello world java";
        for (int i = 0; i < n; i++) sb.append(countWords(sample));
        return sb.toString();
    }

    public static void main(String[] args) {
        buildReport(10_000); buildReport(10_000); buildReport(10_000);
        long start = System.nanoTime();
        buildReport(10_000);
        long ms = (System.nanoTime() - start) / 1_000_000;
        System.out.println("Fixed buildReport(10000) took " + ms + "ms");
        System.out.println("Fixed: StringBuilder replaces +=; static Pattern replaces split re-compile");
        System.out.println("countWords(hello world java) = " + countWords("hello world java"));
    }
}
